//! CMS through this provider, crossed with certval-cms's RustCrypto software in both directions.
//! Keys are generated by Security.framework, in memory, never in a keychain, and exported so that
//! software holds the same key.
//!
//! Enveloping: messages software builds are decrypted with only this provider registered and a
//! `SecurityFrameworkRecipientKey`, and messages this provider builds are decrypted by software.
//! Every key transport algorithm, and ECDH on P-256, P-384 and P-521 with each KDF hash, wrap and
//! user keying material, with AES-CBC content; AES-GCM, which CommonCrypto lacks, is declined.
//!
//! Signing: messages a `SecurityFrameworkSigningKey` signs are verified by software, and messages
//! software signs are verified, and hashed, by this provider alone.
//!
//! Importing: the PKCS #8 software holds, imported by `import_pkcs8`, decrypts and signs as the key
//! Security.framework generated does.
//!
//! ML-KEM, with `pqc`: messages software builds to ML-KEM-768 and ML-KEM-1024 recipients are
//! decrypted by a `CryptoKitRecipientKey`, over a seed and, where the device has one, in the Secure
//! Enclave, and messages this provider builds to them are decrypted by software. ML-KEM-512 is
//! declined.
//!
//! ML-DSA, with `pqc`: messages a `CryptoKitSigningKey` signs with ML-DSA-65 and ML-DSA-87, over a
//! seed and, where the device has one, in the Secure Enclave, are verified by software and by this
//! provider alone. ML-DSA-44 is declined.

#![cfg(all(target_vendor = "apple", feature = "cms"))]

use std::str::FromStr;
use std::sync::Arc;
use std::time::Duration;

use certval::PkiEnvironment;
use certval_cms::{
    rsa_pss, CmsEnvironment, ContentEncryptionAlgorithm, DigestAlgorithm, EnvelopedDataBuilder,
    Error, KeyAgreeRecipient, KeyAgreementAlgorithm, KeyTransRecipient, KeyTransportAlgorithm,
    KeyWrapAlgorithm, RecipientCredential, RecipientCredentialSource, SignedDataBuilder, Signer,
    SignerPolicy, SigningCredential, SoftwareRecipientKey, SoftwareSigningKey,
};
use certval_security_framework::{
    import_pkcs8, KeychainIdentities, SecurityFrameworkCrypto, SecurityFrameworkRecipientKey,
    SecurityFrameworkSigningKey,
};
use cms::{content_info::ContentInfo, enveloped_data::RecipientIdentifier};
use const_oid::db::rfc5912::ID_CE_SUBJECT_KEY_IDENTIFIER;
use der::{asn1::OctetString, Decode, Encode};
use getrandom::SysRng;
use rand_core::UnwrapErr;
use rsa::pkcs1::DecodeRsaPrivateKey;
use rsa::pkcs8::{EncodePrivateKey, EncodePublicKey};
use security_framework::key::{GenerateKeyOptions, KeyType, SecKey};
use sha1::{Digest, Sha1};
use spki::{SubjectPublicKeyInfoOwned, SubjectPublicKeyInfoRef};
use x509_cert::{
    builder::{profile::BuilderProfile, Builder, CertificateBuilder},
    ext::{pkix::SubjectKeyIdentifier, Extension},
    name::Name,
    serial_number::SerialNumber,
    time::Validity,
    Certificate, TbsCertificate,
};

type Rng = UnwrapErr<SysRng>;

const MESSAGE: &[u8] =
    b"certval-security-framework, longer than one AES block so that padding is exercised";

const CBC: [ContentEncryptionAlgorithm; 3] = [
    ContentEncryptionAlgorithm::Aes128Cbc,
    ContentEncryptionAlgorithm::Aes192Cbc,
    ContentEncryptionAlgorithm::Aes256Cbc,
];

const WRAPS: [KeyWrapAlgorithm; 3] = [
    KeyWrapAlgorithm::Aes128,
    KeyWrapAlgorithm::Aes192,
    KeyWrapAlgorithm::Aes256,
];

const DIGESTS: [DigestAlgorithm; 3] = [
    DigestAlgorithm::Sha256,
    DigestAlgorithm::Sha384,
    DigestAlgorithm::Sha512,
];

fn rng() -> Rng {
    UnwrapErr(SysRng)
}

// ---- environments

/// RustCrypto for everything, over a PkiEnvironment of certval's software.
fn software() -> CmsEnvironment {
    let mut pe = PkiEnvironment::default();
    pe.populate_5280_pki_environment();
    let mut env = CmsEnvironment::new();
    env.populate_software();
    env.set_pki_environment(Arc::new(pe));
    env
}

/// This provider for everything it implements, with nothing to fall back to, over a PkiEnvironment
/// holding only this provider.
fn security_framework() -> CmsEnvironment {
    let mut pe = PkiEnvironment::default();
    pe.add_calculate_hash_callback(SecurityFrameworkCrypto::new());
    pe.add_verify_signature_message_callback(SecurityFrameworkCrypto::new());
    pe.add_verify_signature_digest_callback(SecurityFrameworkCrypto::new());
    let mut env = CmsEnvironment::new();
    env.set_pki_environment(Arc::new(pe));
    env.add_encrypt_content_callback(SecurityFrameworkCrypto::new());
    env.add_decrypt_content_callback(SecurityFrameworkCrypto::new());
    env.add_encrypt_key_transport_callback(SecurityFrameworkCrypto::new());
    env.add_encrypt_key_agreement_callback(SecurityFrameworkCrypto::new());
    env
}

// ---- keys and certificates

/// Issues certificates with a subject key identifier from a throwaway P-256 CA.
struct Profile;

impl BuilderProfile for Profile {
    fn get_issuer(&self, _subject: &Name) -> Name {
        Name::from_str("CN=certval-security-framework test CA").unwrap()
    }
    fn get_subject(&self) -> Name {
        Name::from_str("CN=certval-security-framework test").unwrap()
    }
    fn build_extensions(
        &self,
        spk: SubjectPublicKeyInfoRef<'_>,
        _issuer_spk: SubjectPublicKeyInfoRef<'_>,
        _tbs: &TbsCertificate,
    ) -> x509_cert::builder::Result<Vec<Extension>> {
        let skid = SubjectKeyIdentifier(
            OctetString::new(Sha1::digest(spk.subject_public_key.raw_bytes()).to_vec()).unwrap(),
        );
        Ok(vec![Extension {
            extn_id: ID_CE_SUBJECT_KEY_IDENTIFIER,
            critical: false,
            extn_value: OctetString::new(skid.to_der().unwrap()).unwrap(),
        }])
    }
}

fn certificate(spki_der: &[u8]) -> Certificate {
    let ca = p256::ecdsa::SigningKey::from_slice(&[9u8; 32]).unwrap();
    CertificateBuilder::new(
        Profile,
        SerialNumber::new(&[1]).unwrap(),
        Validity::from_now(Duration::from_secs(3600)).unwrap(),
        SubjectPublicKeyInfoOwned::from_der(spki_der).unwrap(),
    )
    .unwrap()
    .build::<_, p256::ecdsa::DerSignature>(&ca)
    .unwrap()
}

/// A key generated by Security.framework, its certificate, and the same key as PKCS #8.
struct Key {
    sec_key: SecKey,
    cert: Certificate,
    pkcs8: Vec<u8>,
}

impl Key {
    fn generate(key_type: KeyType, bits: u32) -> SecKey {
        let mut options = GenerateKeyOptions::default();
        options.set_key_type(key_type).set_size_in_bits(bits);
        SecKey::new(&options).unwrap()
    }

    fn rsa() -> Self {
        let sec_key = Self::generate(KeyType::rsa(), 2048);
        // Security.framework exports an RSA private key as a PKCS #1 RSAPrivateKey.
        let exported = sec_key.external_representation().unwrap().to_vec();
        let key = rsa::RsaPrivateKey::from_pkcs1_der(&exported).unwrap();
        let spki = key.to_public_key().to_public_key_der().unwrap();
        Self {
            sec_key,
            cert: certificate(spki.as_bytes()),
            pkcs8: key.to_pkcs8_der().unwrap().as_bytes().to_vec(),
        }
    }
}

/// An EC key on `$curve`. Security.framework exports an EC private key as the public point
/// followed by the private scalar.
macro_rules! ec_key {
    ($curve:ident, $bits:expr) => {{
        let sec_key = Key::generate(KeyType::ec_sec_prime_random(), $bits);
        let exported = sec_key.external_representation().unwrap().to_vec();
        let scalar_len = usize::div_ceil($bits, 8);
        let key = $curve::SecretKey::from_slice(&exported[exported.len() - scalar_len..]).unwrap();
        let spki = key.public_key().to_public_key_der().unwrap();
        Key {
            sec_key,
            cert: certificate(spki.as_bytes()),
            pkcs8: key.to_pkcs8_der().unwrap().as_bytes().to_vec(),
        }
    }};
}

impl Key {
    fn recipient_credentials(&self) -> (SecurityFrameworkRecipientKey, SoftwareRecipientKey) {
        (
            SecurityFrameworkRecipientKey::new(self.cert.clone(), self.sec_key.clone()),
            SoftwareRecipientKey::from_pkcs8_der(self.cert.clone(), &self.pkcs8).unwrap(),
        )
    }
    fn signing_credentials(&self) -> (SecurityFrameworkSigningKey, SoftwareSigningKey) {
        (
            SecurityFrameworkSigningKey::new(self.cert.clone(), self.sec_key.clone()),
            SoftwareSigningKey::from_pkcs8_der(self.cert.clone(), &self.pkcs8).unwrap(),
        )
    }
}

// ---- enveloping

fn envelop<'e>(
    env: &'e CmsEnvironment,
    alg: ContentEncryptionAlgorithm,
    recipient: impl cms::builder::RecipientInfoBuilder<Rng = Rng> + 'e,
) -> ContentInfo {
    EnvelopedDataBuilder::new(MESSAGE, alg)
        .unwrap()
        .add_recipient(recipient)
        .build_content_info(env, &mut rng())
        .unwrap_or_else(|e| panic!("building: {e}"))
}

fn assert_decrypts(
    env: &CmsEnvironment,
    ci: &ContentInfo,
    credential: &dyn RecipientCredential,
    name: &str,
) {
    let decrypted = env
        .decrypt_enveloped_data(ci, Some(credential))
        .unwrap_or_else(|e| panic!("{name}: {e}"));
    assert_eq!(decrypted.content.as_slice(), MESSAGE, "{name}");
}

#[test]
fn key_transport_with_each_algorithm() {
    let (software, platform) = (software(), security_framework());
    let key = Key::rsa();
    let (platform_key, software_key) = key.recipient_credentials();
    for alg in [
        KeyTransportAlgorithm::RsaPkcs1v15,
        KeyTransportAlgorithm::RsaOaepSha1,
        KeyTransportAlgorithm::RsaOaepSha256,
        KeyTransportAlgorithm::RsaOaepSha384,
        KeyTransportAlgorithm::RsaOaepSha512,
    ] {
        for content in CBC {
            let name = format!("{alg:?} {content:?}");
            let r = KeyTransRecipient::from_certificate(&software, &key.cert, None, alg).unwrap();
            let ci = envelop(&software, content, r);
            assert_decrypts(
                &platform,
                &ci,
                &platform_key,
                &format!("software to Security.framework, {name}"),
            );

            let r = KeyTransRecipient::from_certificate(&platform, &key.cert, None, alg).unwrap();
            let ci = envelop(&platform, content, r);
            assert_decrypts(
                &software,
                &ci,
                &software_key,
                &format!("Security.framework to software, {name}"),
            );
        }
    }
}

fn key_agreement(key: Key, curve: &str) {
    let (software, platform) = (software(), security_framework());
    let (platform_key, software_key) = key.recipient_credentials();
    for alg in [
        KeyAgreementAlgorithm::EcdhSha256,
        KeyAgreementAlgorithm::EcdhSha384,
        KeyAgreementAlgorithm::EcdhSha512,
    ] {
        for wrap in WRAPS {
            for ukm in [None, Some(b"user keying material".to_vec())] {
                let name = format!("{curve} {alg:?} {wrap:?} ukm={}", ukm.is_some());
                let r = KeyAgreeRecipient::from_certificate(
                    &software,
                    &key.cert,
                    None,
                    alg,
                    wrap,
                    ukm.clone(),
                )
                .unwrap();
                let ci = envelop(&software, ContentEncryptionAlgorithm::Aes256Cbc, r);
                assert_decrypts(
                    &platform,
                    &ci,
                    &platform_key,
                    &format!("software to Security.framework, {name}"),
                );

                let r =
                    KeyAgreeRecipient::from_certificate(&platform, &key.cert, None, alg, wrap, ukm)
                        .unwrap();
                let ci = envelop(&platform, ContentEncryptionAlgorithm::Aes128Cbc, r);
                assert_decrypts(
                    &software,
                    &ci,
                    &software_key,
                    &format!("Security.framework to software, {name}"),
                );
            }
        }
    }
}

#[test]
fn key_agreement_on_p256() {
    key_agreement(ec_key!(p256, 256), "P-256");
}

#[test]
fn key_agreement_on_p384() {
    key_agreement(ec_key!(p384, 384), "P-384");
}

#[test]
fn key_agreement_on_p521() {
    key_agreement(ec_key!(p521, 521), "P-521");
}

#[test]
fn aes_gcm_is_declined() {
    let platform = security_framework();
    assert!(matches!(
        platform.encrypt_content(ContentEncryptionAlgorithm::Aes256Gcm, MESSAGE, None),
        Err(Error::Unrecognized)
    ));
}

// ---- signing

fn assert_signs_across(
    signing: &CmsEnvironment,
    verifying: &CmsEnvironment,
    credential: &dyn SigningCredential,
    configure: impl Fn(Signer<'_>) -> Signer<'_>,
    name: &str,
) {
    let ci = SignedDataBuilder::new(MESSAGE)
        .add_signer(configure(Signer::explicit(credential)))
        .build(signing)
        .unwrap_or_else(|e| panic!("{name}: signing: {e}"))
        .content_info;
    let verified = verifying
        .verify_signed_data(&ci, None, None, SignerPolicy::All)
        .unwrap_or_else(|e| panic!("{name}: verifying: {e}"));
    assert_eq!(verified.content, MESSAGE, "{name}");
}

fn sign_both_ways(key: &Key, configure: impl Fn(Signer<'_>) -> Signer<'_> + Copy, name: &str) {
    let (software, platform) = (software(), security_framework());
    let (platform_key, software_key) = key.signing_credentials();
    assert_signs_across(
        &platform,
        &software,
        &platform_key,
        configure,
        &format!("Security.framework signs, software verifies: {name}"),
    );
    assert_signs_across(
        &software,
        &platform,
        &software_key,
        configure,
        &format!("software signs, Security.framework verifies: {name}"),
    );
}

#[test]
fn rsa_pkcs1v15_and_pss_with_each_digest() {
    let key = Key::rsa();
    for digest in DIGESTS {
        sign_both_ways(
            &key,
            |s| s.digest(digest),
            &format!("PKCS #1 v1.5 {digest:?}"),
        );
        sign_both_ways(
            &key,
            |s| {
                s.digest(digest)
                    .signature_algorithm(rsa_pss(digest).unwrap())
            },
            &format!("PSS {digest:?}"),
        );
    }
}

#[test]
fn ecdsa_on_each_curve_with_each_digest() {
    for (key, curve) in [
        (ec_key!(p256, 256), "P-256"),
        (ec_key!(p384, 384), "P-384"),
        (ec_key!(p521, 521), "P-521"),
    ] {
        for digest in DIGESTS {
            sign_both_ways(&key, |s| s.digest(digest), &format!("{curve} {digest:?}"));
        }
    }
}

// ---- the keychain

/// A search of the keychain for a key nobody holds finds nothing. Finding a real identity needs one
/// installed, which a test does not do to a user's keychain.
#[test]
fn a_keychain_search_for_an_absent_key_finds_nothing() {
    let env = CmsEnvironment::new();
    let rid = RecipientIdentifier::SubjectKeyIdentifier(SubjectKeyIdentifier(
        OctetString::new(vec![0xde, 0xad, 0xbe, 0xef]).unwrap(),
    ));
    let found = KeychainIdentities::new().find_recipient_credential(&env, &rid);
    assert!(
        matches!(found, Ok(None)),
        "{:?}",
        found.map(|f| f.is_some())
    );
}

/// Listing the keychain's identities succeeds, whatever it holds.
#[test]
fn the_keychain_lists_its_identities() {
    let certificates = KeychainIdentities::new().certificates().unwrap();
    println!("the keychain holds {} identities", certificates.len());
}

// ---- importing

/// A PKCS #8 key imported by `import_pkcs8` decrypts what software encrypts and signs what software
/// verifies.
fn imported_key_decrypts_and_signs(key: &Key, name: &str) {
    let (software, platform) = (software(), security_framework());
    let (recipient, signer) = import_pkcs8(key.cert.clone(), &key.pkcs8)
        .unwrap_or_else(|e| panic!("{name}: importing: {e}"));
    let r = if key
        .cert
        .tbs_certificate()
        .subject_public_key_info()
        .algorithm
        .oid
        == const_oid::db::rfc5912::RSA_ENCRYPTION
    {
        let r = KeyTransRecipient::from_certificate(
            &software,
            &key.cert,
            None,
            KeyTransportAlgorithm::RsaOaepSha256,
        )
        .unwrap();
        envelop(&software, ContentEncryptionAlgorithm::Aes256Cbc, r)
    } else {
        let r = KeyAgreeRecipient::from_certificate(
            &software,
            &key.cert,
            None,
            KeyAgreementAlgorithm::EcdhSha256,
            KeyWrapAlgorithm::Aes256,
            None,
        )
        .unwrap();
        envelop(&software, ContentEncryptionAlgorithm::Aes256Cbc, r)
    };
    assert_decrypts(&platform, &r, &recipient, name);
    assert_signs_across(&platform, &software, &signer, |s| s, name);
}

#[test]
fn imported_keys_decrypt_and_sign() {
    imported_key_decrypts_and_signs(&Key::rsa(), "RSA");
    imported_key_decrypts_and_signs(&ec_key!(p256, 256), "P-256");
    imported_key_decrypts_and_signs(&ec_key!(p384, 384), "P-384");
    imported_key_decrypts_and_signs(&ec_key!(p521, 521), "P-521");
}

#[test]
fn a_key_that_is_not_the_certificates_is_refused() {
    let (a, b) = (ec_key!(p256, 256), ec_key!(p256, 256));
    assert!(matches!(
        import_pkcs8(a.cert, &b.pkcs8),
        Err(Error::InvalidInput(_))
    ));
    let rsa = Key::rsa();
    assert!(matches!(
        import_pkcs8(rsa.cert, &b.pkcs8),
        Err(Error::InvalidInput(_))
    ));
}

// ---- ML-KEM through CryptoKit

#[cfg(feature = "pqc")]
mod cryptokit_ml_kem {
    use super::*;
    use certval_cms::{KdfAlgorithm, KemRecipient};
    use certval_security_framework::CryptoKitRecipientKey;
    use const_oid::db::fips203::{ID_ALG_ML_KEM_1024, ID_ALG_ML_KEM_768};
    use ml_kem::pkcs8::{EncodePrivateKey, EncodePublicKey};
    use ml_kem::{Kem, MlKem1024, MlKem512, MlKem768};

    const KDFS: [KdfAlgorithm; 3] = [
        KdfAlgorithm::HkdfSha256,
        KdfAlgorithm::HkdfSha384,
        KdfAlgorithm::HkdfSha512,
    ];

    /// This provider, with its ML-KEM encryption registered as well.
    fn security_framework_with_kem() -> CmsEnvironment {
        let mut env = security_framework();
        env.add_encrypt_kem_callback(SecurityFrameworkCrypto::new());
        env
    }

    /// A software ML-KEM key as PKCS #8, and its certificate.
    macro_rules! software_key {
        ($kem:ty) => {{
            let (dk, ek) = <$kem as Kem>::generate_keypair_from_rng(&mut rng());
            let cert = certificate(ek.to_public_key_der().unwrap().as_bytes());
            (cert, dk.to_pkcs8_der().unwrap().as_bytes().to_vec())
        }};
    }

    fn kem_envelop(
        env: &CmsEnvironment,
        cert: &Certificate,
        kdf: KdfAlgorithm,
        wrap: KeyWrapAlgorithm,
        ukm: Option<Vec<u8>>,
    ) -> ContentInfo {
        let r = KemRecipient::from_certificate(env, cert, None, kdf, wrap, ukm).unwrap();
        envelop(env, ContentEncryptionAlgorithm::Aes256Cbc, r)
    }

    /// Both directions, every KDF and wrap, with and without user keying material: software
    /// encrypts and `credential` decrypts under this provider alone, and this provider encrypts
    /// and `software_key` decrypts under software.
    fn crosses(
        cert: &Certificate,
        credential: &dyn RecipientCredential,
        software_key: Option<&dyn RecipientCredential>,
        name: &str,
    ) {
        let (software, platform) = (software(), security_framework_with_kem());
        for kdf in KDFS {
            for wrap in WRAPS {
                for ukm in [None, Some(b"user keying material".to_vec())] {
                    let case = format!("{name} {kdf:?} {wrap:?} ukm={}", ukm.is_some());
                    let ci = kem_envelop(&software, cert, kdf, wrap, ukm.clone());
                    assert_decrypts(
                        &platform,
                        &ci,
                        credential,
                        &format!("software to CryptoKit, {case}"),
                    );

                    let ci = kem_envelop(&platform, cert, kdf, wrap, ukm);
                    assert_decrypts(
                        &platform,
                        &ci,
                        credential,
                        &format!("CryptoKit to CryptoKit, {case}"),
                    );
                    if let Some(software_key) = software_key {
                        assert_decrypts(
                            &software,
                            &ci,
                            software_key,
                            &format!("CryptoKit to software, {case}"),
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn ml_kem_768_and_1024_from_pkcs8() {
        if !SecurityFrameworkCrypto::ml_kem_available() {
            println!("ML-KEM: skipped, the running OS has no CryptoKit ML-KEM");
            return;
        }
        for (cert, pkcs8, name) in [
            {
                let (c, k) = software_key!(MlKem768);
                (c, k, "ML-KEM-768")
            },
            {
                let (c, k) = software_key!(MlKem1024);
                (c, k, "ML-KEM-1024")
            },
        ] {
            let credential = CryptoKitRecipientKey::from_pkcs8_der(cert.clone(), &pkcs8)
                .unwrap_or_else(|e| panic!("{name}: {e}"));
            let software_key = SoftwareRecipientKey::from_pkcs8_der(cert.clone(), &pkcs8).unwrap();
            crosses(&cert, &credential, Some(&software_key), name);
        }
    }

    #[test]
    fn ml_kem_in_the_secure_enclave() {
        if !SecurityFrameworkCrypto::ml_kem_available()
            || !SecurityFrameworkCrypto::secure_enclave_available()
        {
            println!("Secure Enclave ML-KEM: skipped, no Secure Enclave or no CryptoKit ML-KEM");
            return;
        }
        for (oid, name) in [
            (ID_ALG_ML_KEM_768, "ML-KEM-768"),
            (ID_ALG_ML_KEM_1024, "ML-KEM-1024"),
        ] {
            let (data, spki) = CryptoKitRecipientKey::generate_in_secure_enclave(oid)
                .unwrap_or_else(|e| panic!("{name}: generating: {e}"));
            let cert = certificate(&spki.to_der().unwrap());
            let credential = CryptoKitRecipientKey::from_secure_enclave(cert.clone(), data)
                .unwrap_or_else(|e| panic!("{name}: {e}"));
            crosses(&cert, &credential, None, &format!("Secure Enclave {name}"));
        }
    }

    #[test]
    fn ml_kem_512_is_declined() {
        let (cert, pkcs8) = software_key!(MlKem512);
        assert!(matches!(
            CryptoKitRecipientKey::from_pkcs8_der(cert.clone(), &pkcs8),
            Err(Error::Unrecognized)
        ));
        let platform = security_framework_with_kem();
        let r = KemRecipient::from_certificate(
            &platform,
            &cert,
            None,
            KdfAlgorithm::HkdfSha256,
            KeyWrapAlgorithm::Aes256,
            None,
        )
        .unwrap();
        let built = EnvelopedDataBuilder::new(MESSAGE, ContentEncryptionAlgorithm::Aes256Cbc)
            .unwrap()
            .add_recipient(r)
            .build_content_info(&platform, &mut rng());
        assert!(built.is_err(), "ML-KEM-512 was not declined");
    }

    #[test]
    fn a_key_that_is_not_the_certificates_is_refused() {
        if !SecurityFrameworkCrypto::ml_kem_available() {
            println!("ML-KEM: skipped, the running OS has no CryptoKit ML-KEM");
            return;
        }
        let (cert, _) = software_key!(MlKem768);
        let (_, other) = software_key!(MlKem768);
        assert!(matches!(
            CryptoKitRecipientKey::from_pkcs8_der(cert, &other),
            Err(Error::InvalidInput(_))
        ));
        if SecurityFrameworkCrypto::secure_enclave_available() {
            let (data, _) =
                CryptoKitRecipientKey::generate_in_secure_enclave(ID_ALG_ML_KEM_768).unwrap();
            let (cert, _) = software_key!(MlKem768);
            assert!(matches!(
                CryptoKitRecipientKey::from_secure_enclave(cert, data),
                Err(Error::InvalidInput(_))
            ));
        }
    }
}

// ---- ML-DSA signing through CryptoKit

#[cfg(feature = "pqc")]
mod cryptokit_ml_dsa {
    use super::*;
    use certval_security_framework::CryptoKitSigningKey;
    use const_oid::db::fips204::{ID_ML_DSA_65, ID_ML_DSA_87};
    use ml_dsa::pkcs8::{EncodePrivateKey, EncodePublicKey};
    use ml_dsa::{MlDsa44, MlDsa65, MlDsa87};
    use rand_core::Rng as _;
    use signature::Keypair;

    /// A software ML-DSA key as PKCS #8, in the seed form, and its certificate.
    macro_rules! software_key {
        ($params:ty) => {{
            let mut seed = [0u8; 32];
            rng().fill_bytes(&mut seed);
            let key = ml_dsa::SigningKey::<$params>::from_seed(&seed.into());
            let cert = certificate(key.verifying_key().to_public_key_der().unwrap().as_bytes());
            (cert, key.to_pkcs8_der().unwrap().as_bytes().to_vec())
        }};
    }

    /// `credential` signs under this provider alone, and the signature is verified by software and
    /// by this provider.
    fn verifies_both_ways(credential: &CryptoKitSigningKey, name: &str) {
        let platform = security_framework();
        assert_signs_across(
            &platform,
            &software(),
            credential,
            |s| s,
            &format!("CryptoKit signs, software verifies: {name}"),
        );
        assert_signs_across(
            &platform,
            &platform,
            credential,
            |s| s,
            &format!("CryptoKit signs, Security.framework verifies: {name}"),
        );
    }

    #[test]
    fn ml_dsa_65_and_87_from_pkcs8() {
        if !SecurityFrameworkCrypto::ml_dsa_available() {
            println!("ML-DSA: skipped, the running OS has no CryptoKit ML-DSA");
            return;
        }
        for (cert, pkcs8, name) in [
            {
                let (c, k) = software_key!(MlDsa65);
                (c, k, "ML-DSA-65")
            },
            {
                let (c, k) = software_key!(MlDsa87);
                (c, k, "ML-DSA-87")
            },
        ] {
            let credential = CryptoKitSigningKey::from_pkcs8_der(cert, &pkcs8)
                .unwrap_or_else(|e| panic!("{name}: {e}"));
            verifies_both_ways(&credential, name);
        }
    }

    #[test]
    fn ml_dsa_in_the_secure_enclave() {
        if !SecurityFrameworkCrypto::ml_dsa_available()
            || !SecurityFrameworkCrypto::secure_enclave_available()
        {
            println!("Secure Enclave ML-DSA: skipped, no Secure Enclave or no CryptoKit ML-DSA");
            return;
        }
        for (oid, name) in [(ID_ML_DSA_65, "ML-DSA-65"), (ID_ML_DSA_87, "ML-DSA-87")] {
            let (data, spki) = CryptoKitSigningKey::generate_in_secure_enclave(oid)
                .unwrap_or_else(|e| panic!("{name}: generating: {e}"));
            let cert = certificate(&spki.to_der().unwrap());
            let credential = CryptoKitSigningKey::from_secure_enclave(cert, data)
                .unwrap_or_else(|e| panic!("{name}: {e}"));
            verifies_both_ways(&credential, &format!("Secure Enclave {name}"));
        }
    }

    #[test]
    fn ml_dsa_44_is_declined() {
        let (cert, pkcs8) = software_key!(MlDsa44);
        assert!(matches!(
            CryptoKitSigningKey::from_pkcs8_der(cert, &pkcs8),
            Err(Error::Unrecognized)
        ));
        assert!(matches!(
            CryptoKitSigningKey::generate_in_secure_enclave(const_oid::db::fips204::ID_ML_DSA_44),
            Err(Error::Unrecognized)
        ));
    }

    #[test]
    fn a_key_that_is_not_the_certificates_is_refused() {
        if !SecurityFrameworkCrypto::ml_dsa_available() {
            println!("ML-DSA: skipped, the running OS has no CryptoKit ML-DSA");
            return;
        }
        let (cert, _) = software_key!(MlDsa65);
        let (_, other) = software_key!(MlDsa65);
        assert!(matches!(
            CryptoKitSigningKey::from_pkcs8_der(cert, &other),
            Err(Error::InvalidInput(_))
        ));
        if SecurityFrameworkCrypto::secure_enclave_available() {
            let (data, _) = CryptoKitSigningKey::generate_in_secure_enclave(ID_ML_DSA_65).unwrap();
            let (cert, _) = software_key!(MlDsa65);
            assert!(matches!(
                CryptoKitSigningKey::from_secure_enclave(cert, data),
                Err(Error::InvalidInput(_))
            ));
        }
    }
}
